    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (residual - next).abs();

        if residual >= next {
            score -= next * 1.18;
            let surplus = residual - next;
            score += surplus * surplus / (capacity + 1.0) * 0.17;
            if surplus < next * 0.22 {
                score -= surplus * 0.22;
            }
        } else {
            score += (next - residual) * 0.61;
        }

        let combined = size + next;
        if residual >= combined {
            score -= next * 0.72;
        } else if residual + next <= capacity * 0.5 {
            score += (capacity - residual - next) * 0.035;
        }
    }

    if mean_residual > 0.0 {
        let deviation = (mean_residual - residual).abs();
        score += deviation * 0.12
            + deviation * deviation / (mean_residual + 1.0) * 0.13;
    }

    if fitting_bins_count == 0 {
        score += 6.4;
    } else if fitting_bins_count == 1 {
        score += 1.85;
    } else if fitting_bins_count == 2 {
        score += 0.38;
    } else if fitting_bins_count >= 4 {
        score -= (fitting_bins_count as f64 - 3.0) * 0.24;
    }

    let pressure = (1.0 - progress) * (open_bins_count as f64).sqrt() * 0.071;
    score += pressure;

    if item_size >= 60 {
        if residual == 0.0 {
            score -= 4.0;
        } else if residual < 14.0 {
            score += 2.35;
        } else {
            score += residual * 0.042;
        }
    } else if residual == 0.0 {
        score -= 1.8;
    } else if residual < item_size as f64 * 0.18 {
        score += residual * 0.31;
    }

    if size > capacity * 0.67 && residual > 0.0 {
        score += residual * 0.085;
    }

    if residual > 0.0 && residual < next_item_size as f64 {
        score += (next_item_size as f64 - residual) * 0.09;
    }

    if residual > capacity * 0.72 && size < capacity * 0.35 {
        score += (residual - capacity * 0.5) * 0.075;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let item = item_size as f64;
    let residual = post_residual as f64;
    let capacity = bin_capacity as f64;
    let next = next_item_size as f64;
    let mut score = residual;

    if bin_residual == bin_capacity {
        // ---- brand-new empty bin candidate ----
        score += 118.0;

        if open_bins_count == 0 {
            score -= 158.0;
        }
        // Scarcity of alternatives: opening a new bin is cheap only when
        // few open bins could absorb the item at all.
        if fitting_bins_count == 0 {
            score -= 150.0;
        } else if fitting_bins_count == 1 {
            // one alternative exists -> mildly prefer it, but the new bin
            // keeps future flexibility, so bias against opening.
            score -= 26.0;
        } else if fitting_bins_count == 2 {
            score -= 4.0;
        } else {
            score += 16.0 * (fitting_bins_count as f64 - 3.0).min(4.0);
        }

        // Wastefulness: mean open-bin residual far above the item means the
        // existing fleet is loose, so use it instead of starting over.
        let spread = mean_residual - item;
        if spread > 0.0 {
            score += (spread * 1.45).min(52.0);
        } else {
            // existing bins are already tight: opening is more defensible
            score -= 14.0;
        }

        // Lookahead: if the next item is smaller, a fresh bin can host both.
        if next > 0.0 && next <= item {
            score -= 19.0;
            if next + 2.0 >= item {
                score -= 6.0;
            }
        }
        // If next item is bigger than this one, a fresh bin wastes room.
        if next > item {
            score += (next - item) * 0.9;
        }

        let progress = if total_items > 0 {
            step_index as f64 / total_items as f64
        } else {
            0.0
        };
        if progress > 0.94 {
            score -= 9.0;
        }
    } else {
        let fill_ratio = 1.0 - residual / capacity;
        let relative_residual = residual / capacity;
        score -= 142.0 * fill_ratio;

        // Dead space charge: residual that no plausible item can use.
        let dead_space_penalty = if residual > 0.0 && residual < 7.0 {
            (7.0 - residual) * 6.4
        } else if residual > 0.0 && residual < item {
            (item - residual) * 2.35
        } else {
            0.0
        };
        score += dead_space_penalty;

        if residual == 0.0 {
            score -= 43.0;
        } else if residual < item {
            score += (item - residual) * 1.12;
        }

        // Lookahead: room for the following item.
        if next > 0.0 && residual >= next {
            score -= 42.0;
            if residual == next {
                score -= 31.0;
            } else if residual <= next + 2.0 {
                score -= 13.0;
            } else if residual <= next + 5.0 {
                score -= 5.0;
            }
        }

        // Prefer residuals near the fleet mean to keep residuals homogeneous
        // (lower residual variance -> fewer wasted half bins).
        let residual_gap = residual - mean_residual;
        score += 0.64 * residual_gap;

        if fitting_bins_count <= 1 {
            score += 74.0;
            if next == 0.0 || next > residual {
                score += 31.0;
            }
        } else if fitting_bins_count == 2 {
            score += 18.0;
        }

        let progress = if total_items > 0 {
            step_index as f64 / total_items as f64
        } else {
            0.0
        };
        score += (1.0 - progress) * 14.0;

        if open_bins_count > 1 && mean_residual < item {
            score -= 20.0;
        }
        if residual == item {
            score -= 23.0;
        }

        if fill_ratio > 0.91 {
            score -= 21.0 * (fill_ratio - 0.91) / 0.09;
        }

        if fill_ratio < 0.55 && residual >= item {
            score += 22.0 * (0.55 - fill_ratio);
            if relative_residual > 0.38 {
                score += (relative_residual - 0.38) * 48.0;
            }
        }

        if next > 0.0 && residual > 0.0 && residual < next {
            let miss = next - residual;
            score += miss * 0.86;
            if fitting_bins_count > 1 {
                score += (miss / next).min(1.0) * 12.0;
            }
        }

        // ---- COMBINED: fine-grained residual fitting + two-step lookahead ----
        if next > 0.0 && residual >= next {
            let two_item_fit = residual >= item + next;
            let next_slack = residual - next;
            if two_item_fit {
                // room for both current and next item: strongly desirable
                score -= 11.0;
                // quantify how much slack is left over after both items
                let triple_room = residual - item - next;
                if triple_room > 0.0 {
                    score -= (triple_room.min(12.0)) * 0.55;
                }
            }
            if next_slack <= 3.0 {
                score -= 7.0;
            }
            // Reward bins that leave a *tight* but useful remainder for the
            // item after next: residual - item close to a plausible size.
            let leftover = residual - item;
            if leftover > 0.0 {
                if leftover <= 6.0 {
                    score -= (6.0 - leftover) * 1.35;
                } else if leftover <= 18.0 {
                    score -= 4.0;
                }
            }
        }

        // Dead space proportional charge (small residual nearly useless).
        if residual > 0.0 && residual < item {
            score += (residual / item.min(capacity)) * 18.0;
        }

        // Residual-vs-mean coupling: strongly penalize residuals far above the
        // mean (they hoard space) and mildly reward those below it.
        if residual_gap > 0.0 {
            score += residual_gap * residual_gap * 0.22;
        } else if residual_gap < 0.0 {
            score += residual_gap * 0.9;
        }

        // Non-linear penalty: bins whose residual sits in the "unusable band"
        // (small but non-zero and below the next item) are the worst case.
        if residual > 0.0 && residual < item {
            let band = (item - residual).min(residual);
            score += band * 0.75;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: u32) -> f64 {
    let item = item_size as f64;
    let residual = post_residual as f64;
    let capacity = bin_capacity.max(1) as f64;
    let fitted_fraction = (item / capacity).clamp(0.0, 1.0);

    let mut score = residual;

    if bin_residual == bin_capacity {
        score -= capacity * 0.72;
    }

    if next_item_size > 0 {
        let next = next_item_size as f64;
        if residual >= next {
            score -= next * 3.2;
        } else {
            score += (next - residual) * 1.85;
        }

        let deviation = (mean_residual - residual).abs();
        score -= deviation * 0.22;

        if residual >= next {
            let usable_slack = (residual - next).min(capacity);
            score -= usable_slack * 0.08;
        } else {
            let fit_ratio = next / capacity;
            score += fit_ratio * 2.4;
        }
    } else {
        score -= residual * 0.04;
    }

    let scarcity = if fitting_bins_count == 0 {
        5.5
    } else if fitting_bins_count == 1 {
        2.2
    } else {
        0.0
    };
    score += scarcity;

    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    let pressure = (1.0 - progress) * (open_bins_count as f64).sqrt() * 0.11;
    score += pressure;

    if item >= 55.0 && residual > 0.0 && residual < 12.0 {
        score += (residual + 3.0) * 0.45;
    } else if residual == 0.0 {
        score -= 4.0;
    }

    if fitted_fraction >= 0.75 {
        score -= (fitted_fraction - 0.75) * 8.0;
    } else if fitted_fraction <= 0.25 {
        score += (0.25 - fitted_fraction) * 3.0;
    }

    if fitting_bins_count > 1 {
        let diversity = (fitting_bins_count as f64).sqrt() * 0.16;
        score += diversity;
    }

    if open_bins_count > 1 && residual > capacity * 0.72 {
        score += residual * 0.035;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let residual = post_residual as f64;
    let capacity = bin_capacity as f64;
    let size = item_size as f64;

    // Prefer tightly filled bins, but preserve a little slack for nearby items.
    let mut score = residual * 0.42;

    // A nearly empty bin is attractive only when the incoming item is large.
    let fill_ratio = if capacity > 0.0 {
        1.0 - residual / capacity
    } else {
        0.0
    };
    score -= fill_ratio * capacity * 0.11;

    // New bins receive a dynamic opening premium/penalty based on alternatives.
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            score -= capacity * 0.34;
        } else {
            score += capacity * 0.12;
        }
    }

    // Use the next item as a local lookahead, allowing a slightly imperfect
    // current placement when it creates a much better future fit.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if residual >= next {
            score -= next * 1.35;
        } else {
            score += (next - residual) * 0.85;
        }

        // Avoid creating many isolated tiny remainders.
        if residual > 0.0 && residual < next {
            score += (next - residual) * 0.12;
        }
    } else {
        score -= residual * 0.03;
    }

    // Prefer bins whose residual is close to the population average, with a
    // soft quadratic penalty for unusually large or unusually tiny gaps.
    if mean_residual > 0.0 {
        let deviation = (mean_residual - residual).abs();
        score += deviation * 0.18 + deviation * deviation / (mean_residual + 1.0) * 0.08;
    }

    // Scarcity of fitting alternatives increases the value of using one now.
    if fitting_bins_count == 0 {
        score += 7.0;
    } else if fitting_bins_count == 1 {
        score += 2.2;
    } else if fitting_bins_count == 2 {
        score += 0.55;
    }

    // Mid-stream pressure gently rewards consolidation; it fades near the end.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    let pressure = (1.0 - progress) * (open_bins_count as f64).sqrt() * 0.085;
    score += pressure;

    // Large items should close a bin when possible instead of leaving a
    // residual that is unlikely to be useful for the remaining stream.
    if item_size >= 60 {
        if residual == 0 {
            score -= 4.5;
        } else if residual < 12 {
            score += 3.2;
        } else {
            score += residual * 0.06;
        }
    } else if residual == 0 {
        score -= 2.0;
    } else if residual < item_size / 5 {
        score += residual * 0.35;
    }

    // Account for the fact that a very tight fit may make the bin unavailable
    // for subsequent medium-sized items.
    if next_item_size > 0 && residual >= next_item_size && residual < next_item_size * 2 {
        score += 0.65;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if bin_residual == bin_capacity {
        score -= bin_capacity as f64;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 2.5;
        } else {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }

        score -= (mean_residual - post_residual as f64).abs() * 0.35;
    } else {
        score -= post_residual as f64 * 0.05;
    }

    let scarcity = if fitting_bins_count == 0 {
        4.0
    } else if fitting_bins_count == 1 {
        2.5
    } else {
        0.0
    };
    score += scarcity;

    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    let pressure = (1.0 - progress) * (open_bins_count as f64).sqrt() * 0.15;
    score += pressure;

    if item_size >= 60 && post_residual > 0 && post_residual < 10 {
        score += 8.0;
    } else if post_residual == 0 {
        score -= 3.0;
    }

    score
}
